INSERT INTO `agri_algorithm_config` VALUES (1,'coverage','覆盖优化算法','{\"coverageTarget\":0.90,\"sensorRadius\":3.0,\"maxIterations\":1000}','基于贪心策略的网格覆盖优化算法，逐步放置传感器节点直到覆盖率达到目标值，减少监测盲区。','0','admin','2026-04-14 23:08:40'),(2,'cluster','分簇优化算法','{\"clusterCount\":5,\"maxIterations\":100,\"energyThreshold\":0.1}','基于LEACH协议思想的分簇优化算法，随机选举簇头节点，非簇头节点就近加入簇，均衡节点能耗。','0','admin','2026-04-14 23:08:40');
