--
-- Table structure for table `agri_deploy_scheme`
--

DROP TABLE IF EXISTS `agri_deploy_scheme`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `agri_deploy_scheme` (
  `scheme_id` bigint NOT NULL AUTO_INCREMENT COMMENT '方案ID',
  `scheme_name` varchar(200) DEFAULT NULL COMMENT '方案名称',
  `farmland_id` bigint NOT NULL COMMENT '农田ID',
  `algorithm_type` varchar(20) NOT NULL COMMENT '算法类型（coverage/cluster）',
  `node_count` int DEFAULT NULL COMMENT '节点数量',
  `coverage_rate` decimal(5,2) DEFAULT NULL COMMENT '覆盖率(%)',
  `energy_balance` decimal(5,2) DEFAULT NULL COMMENT '能耗均衡度(%)',
  `result_json` text COMMENT '部署结果JSON',
  `user_id` bigint DEFAULT NULL COMMENT '所属用户ID',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '状态（0待确认 1已确认 2已废弃）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`scheme_id`)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='部署方案表';
/*!40101 SET character_set_client = @saved_cs_client */;

