--
-- Table structure for table `agri_env_data`
--

DROP TABLE IF EXISTS `agri_env_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `agri_env_data` (
  `data_id` bigint NOT NULL AUTO_INCREMENT COMMENT '数据ID',
  `farmland_id` bigint NOT NULL COMMENT '农田ID',
  `temperature` decimal(5,2) DEFAULT NULL COMMENT '温度(℃)',
  `humidity` decimal(5,2) DEFAULT NULL COMMENT '湿度(%)',
  `light_intensity` decimal(10,2) DEFAULT NULL COMMENT '光照强度(lux)',
  `soil_moisture` decimal(5,2) DEFAULT NULL COMMENT '土壤含水量(%)',
  `wind_speed` decimal(5,2) DEFAULT NULL COMMENT '风速(m/s)',
  `record_time` datetime DEFAULT NULL COMMENT '记录时间',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`data_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2048 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='环境参数数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

