DROP TABLE IF EXISTS `agri_error_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `agri_error_log` (
  `error_id` bigint NOT NULL AUTO_INCREMENT COMMENT '错误ID',
  `error_type` varchar(50) DEFAULT NULL COMMENT '错误类型（DATA_FORMAT/ALGORITHM_FAIL/UPLOAD_FAIL等）',
  `error_msg` varchar(500) DEFAULT NULL COMMENT '错误提示信息',
  `stack_trace` text COMMENT '堆栈信息',
  `request_url` varchar(200) DEFAULT NULL COMMENT '请求URL',
  `request_param` text COMMENT '请求参数',
  `user_id` bigint DEFAULT NULL COMMENT '操作用户ID',
  `user_name` varchar(64) DEFAULT NULL COMMENT '用户名',
  `create_time` datetime DEFAULT NULL COMMENT '发生时间',
  PRIMARY KEY (`error_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='业务错误日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

