--
-- Table structure for table `agri_farmland`
--

DROP TABLE IF EXISTS `agri_farmland`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `agri_farmland` (
  `farmland_id` bigint NOT NULL AUTO_INCREMENT COMMENT '农田ID',
  `farmland_name` varchar(100) NOT NULL COMMENT '农田名称',
  `boundary_data` text COMMENT '边界坐标JSON [[x1,y1],[x2,y2]...]',
  `area` decimal(12,2) DEFAULT NULL COMMENT '面积（亩）',
  `crop_type` varchar(50) DEFAULT NULL COMMENT '作物类型',
  `grid_rows` int NOT NULL DEFAULT '20' COMMENT '网格行数',
  `grid_cols` int NOT NULL DEFAULT '20' COMMENT '网格列数',
  `user_id` bigint DEFAULT NULL COMMENT '所属用户ID',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`farmland_id`)
